class Solution {
  public int movesToChessboard(int[][] board) {
    int n = board.length;
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++)
        if ((board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]) != 0) return -1;
    int rowOnes = 0, colOnes = 0;
    for (int i = 0; i < n; i++) {
      rowOnes += board[0][i];
      colOnes += board[i][0];
    }
    if (rowOnes < n / 2 || rowOnes > (n + 1) / 2 || colOnes < n / 2 || colOnes > (n + 1) / 2)
      return -1;
    int rowMoves = 0, colMoves = 0;
    for (int i = 0; i < n; i++) {
      rowMoves += board[i][0] == (i % 2) ? 0 : 1;
      colMoves += board[0][i] == (i % 2) ? 0 : 1;
    }
    if ((n & 1) == 1) {
      // odd n: only one of the two patterns is reachable, the one needing an even number of fixes
      if (rowMoves % 2 == 1) rowMoves = n - rowMoves;
      if (colMoves % 2 == 1) colMoves = n - colMoves;
    } else {
      rowMoves = Math.min(rowMoves, n - rowMoves);
      colMoves = Math.min(colMoves, n - colMoves);
    }
    return (rowMoves + colMoves) / 2;
  }
}
